/* eslint-disable @next/next/no-img-element */
import type { ReactNode } from "react";

// iPhone-Rahmen für Screenshots und Simulationen der nativen App (Generated by
// Claude Code). Bildschirm-Inhalte werden in echter iPhone-Breite (402 pt)
// gestaltet und dann skaliert, damit Schriftgrößen und Abstände der App 1:1
// stimmen.
const SCREEN_W = 402;
const SCREEN_H = 874;
const BEZEL = 10;

export function PhoneFrame({
  width = 300,
  children,
  className = "",
  label,
}: {
  width?: number;
  children: ReactNode;
  className?: string;
  label: string;
}) {
  const inner = width - BEZEL * 2;
  const scale = inner / SCREEN_W;
  const innerHeight = SCREEN_H * scale;
  return (
    <figure
      aria-label={label}
      className={`relative shrink-0 bg-[#0c0c0d] ${className}`}
      style={{ width, height: innerHeight + BEZEL * 2, padding: BEZEL, borderRadius: width * 0.17 }}
    >
      <div className="relative overflow-hidden bg-white" style={{ width: inner, height: innerHeight, borderRadius: width * 0.145 }}>
        <div style={{ width: SCREEN_W, height: SCREEN_H, transform: `scale(${scale})`, transformOrigin: "top left" }}>{children}</div>
      </div>
    </figure>
  );
}

/** Echter App-Screenshot (enthält Statusleiste und Dynamic Island bereits). */
export function Screenshot({ src, alt, eager = false }: { src: string; alt: string; eager?: boolean }) {
  return (
    <img
      src={src}
      alt={alt}
      width={SCREEN_W}
      height={SCREEN_H}
      className="block h-full w-full object-cover"
      loading={eager ? "eager" : "lazy"}
    />
  );
}

