/** Schwebende Tab-Leiste der App (Liquid Glass), aktiver Tab hervorgehoben. */
export function TabBar({ active }: { active: "home" | "suche" | "karte" | "kalender" | "profil" }) {
  const tabs = [
    { id: "home", label: "Home", path: "M4 11.5 12 4l8 7.5V20a1 1 0 0 1-1 1h-4.5v-6h-5v6H5a1 1 0 0 1-1-1v-8.5Z" },
    { id: "suche", label: "Suche", path: "M10.5 4a6.5 6.5 0 1 0 4 11.6l4.2 4.2 1.4-1.4-4.2-4.2A6.5 6.5 0 0 0 10.5 4Zm0 2a4.5 4.5 0 1 1 0 9 4.5 4.5 0 0 1 0-9Z" },
    { id: "karte", label: "Karte", path: "M3 6.5 8.5 4l7 2.5L21 4v13.5L15.5 20l-7-2.5L3 20V6.5Z" },
    { id: "kalender", label: "Kalender", path: "M5 5h14a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2Zm0 5v9h14v-9H5Zm2-7h2v4H7V3Zm8 0h2v4h-2V3Z" },
    { id: "profil", label: "Profil", path: "M12 4a4 4 0 1 1 0 8 4 4 0 0 1 0-8Zm0 10c4.4 0 8 2.2 8 5v1H4v-1c0-2.8 3.6-5 8-5Z" },
  ] as const;
  return (
    <div className="absolute inset-x-[20px] bottom-[22px] z-20 flex h-[62px] items-center justify-between rounded-full border border-white/70 bg-white/80 px-[6px] shadow-[0_8px_30px_rgba(0,0,0,0.08)] backdrop-blur-xl" aria-hidden="true">
      {tabs.map((tab) => {
        const isActive = tab.id === active;
        return (
          <span
            key={tab.id}
            className={`flex h-[52px] w-[68px] flex-col items-center justify-center gap-[2px] rounded-full ${isActive ? "bg-black/[0.06]" : ""}`}
          >
            <svg width="24" height="24" viewBox="0 0 24 24" fill={isActive ? "#146194" : "#111111"}>
              <path d={tab.path} fillRule="evenodd" />
            </svg>
            <span style={{ font: "500 11px -apple-system, 'SF Pro Text', system-ui, sans-serif", color: isActive ? "#146194" : "#111111" }}>
              {tab.label}
            </span>
          </span>
        );
      })}
    </div>
  );
}
